# Generated data for 2021-12-set1
SUBPARTS = [{'id': '2021-12-set1-conv-1', 'subpart_code': 'conv-1', 'section_id': '2021-12-set1-sec-a', 'section_title': 'Section A: Long Conversations', 'type': 'conversation', 'title': 'Conversation 1 · 大学好友探讨咽喉感染、冰上滑倒摔坏电脑与维修推荐', 'topic_zh': '大学好友探讨咽喉感染、冰上滑倒摔坏电脑与维修推荐', 'question_range': 'Q1 ~ Q4', 'questions': [1, 2, 3, 4], 'sp_start': 47.0, 'sp_end': 163.0, 'sentences': [('W', "Hi, David. I haven't seen you in class for almost two weeks.", '嗨，大卫。我已经差不多两个星期没在课堂上见到你了。'), ('W', 'We thought you had disappeared on holiday early or something.', '我们还以为你提前去度假或者去别的地方了呢。'), ('M', "Hi, Sarah. Well, it's a bit of a long story, I'm afraid.", '嗨，萨拉。唉，恐怕说来话长了。'), ('M', "I got a throat infection last week and had to go to the hospital to get some antibiotics as I really wasn't getting any better.", '我上周喉咙严重感染，不得不去医院开一些抗生素，因为病情实在不见好转。'), ('W', 'Oh, yeah. There have been so many viruses going around this winter.', '噢，天哪。今年冬天确实有好多病毒到处流行。'), ('W', 'The weather has been so awful for the last few weeks.', '过去几周的天气也实在太恶劣了。'), ('M', "And, on the way back from the hospital, I slipped on some ice and fell and then had to go to the hospital to get an X-ray because I basically thought I broke my wrist, although, thankfully, it's not broken.", '而且，在从医院回来的路上，我在结冰的路面上滑倒摔了一跤，不得不又去医院拍了X光片，因为我当时以为把手腕摔断了，不过万幸的是没骨折。'), ('M', 'But I need to be careful with it for the next few weeks.', '不过接下来的几周我得格外当心这只手。'), ('W', "Oh, that's too bad! How unfortunate!", '天啊，那太糟糕了！真是太倒霉了！'), ('M', 'To make things worse, I managed to fall right in front of four girls from the ninth grade.', '更尴尬的是，我偏偏摔倒在四个初三女生面前。'), ('M', 'So I was utterly humiliated.', '所以当时我简直无地自容、丢脸极了。'), ('M', 'Plus, the laptop in my bag was broken too.', '而且，我书包里的笔记本电脑也摔坏了。'), ('W', 'No, what a complete catastrophe!', '天呐，这可真是祸不单行的大灾难！'), ('W', 'Is the laptop still under warranty?', '笔记本电脑还在保修期内吗？'), ('W', "If it is, then you can easily send it back to the manufacturer, and they'll send you a brand-new one for free surely.", '如果还在保的话，你就可以轻松把它寄回原厂，他们肯定会免费给你换一台全新的。'), ('M', 'The warranty ran out three days before I broke it.', '坏掉的前三天，保修期刚好到期了。'), ('M', 'And all my essays are in there, and I need to hand them in before we break for the Christmas holidays.', '而且我所有的期末论文全都在里面，我必须在圣诞放假前全部交上去。'), ('W', 'Listen, I have the number of a really good, affordable computer repair shop at home.', '听我说，我家里有一家非常靠谱、收费合理的电脑维修店的电话号码。'), ('W', 'My dad has used this guy before and he can work miracles.', '我爸以前找过那个师傅，他技术神乎其神、能妙手回春。'), ('W', "Let's go back to my house and we can call the repair shop, and you can have some tea and cookies too.", '走，去我家吧，我们可以给维修店打电话，你还可以在我家喝点茶、吃点曲奇饼干。'), ('M', 'Wow, thanks, Sarah! That would be great!', '哇，太感谢你了，萨拉！那真是太好了！'), ('M', "Let me just call my mom and let her know I'll be home a little bit later.", '我先给我妈打个电话，告诉她我会晚一点回家。')]}, {'id': '2021-12-set1-conv-2', 'subpart_code': 'conv-2', 'section_id': '2021-12-set1-sec-a', 'section_title': 'Section A: Long Conversations', 'type': 'conversation', 'title': 'Conversation 2 · 军事历史学家转型创作未来科幻小说的创作心路', 'topic_zh': '军事历史学家转型创作未来科幻小说的创作心路', 'question_range': 'Q5 ~ Q8', 'questions': [5, 6, 7, 8], 'sp_start': 236.0, 'sp_end': 363.0, 'sentences': [('M', "Welcome to this week's episode of Book Talk.", '欢迎收听本周的《书话天下》节目。'), ('M', 'With me today is Heidi Brown, a historian who has written five critically acclaimed books about military history.', '今天做客我们节目的是海蒂·布朗，她是一位著有五部广受赞誉的军事史著作的历史学家。'), ('W', 'Thanks for having me, John.', '谢谢你邀请我，约翰。'), ('W', "I'm so excited to talk about my latest book, which was published last month.", '我非常激动能在这里聊聊我上个月刚出版的新书。'), ('M', 'So this book is a novel, your first attempt at that genre.', '这部新书是一本小说，也是你首次尝试这一文学题材。'), ('M', 'I thought it was a bit of a departure for you.', '我觉得这对你而言算是一次不小的突破和转变。'), ('W', "I'd say it's a major departure as it's not just a work of fiction.", '我认为这是一次重大突破，因为它绝非只是一部普通的虚构小说。'), ('W', "It's set 200 years in the future.", '它的故事背景设定在200年后的未来。'), ('M', 'Right. So how did that happen?', '好的。那么这一转变是如何发生的呢？'), ('M', "You spent three decades writing about the past and focusing on the 18th and 19th centuries, and now you're speculating about the future.", '你花了三十年时间研究历史、专注于18和19世纪，而如今你却在推想预测未来。'), ('W', 'Well, after years of researching soldiers and chronicling their lives during battle, I just started wondering about other facets of their lives, especially their personal lives.', '嗯，在多年研究士兵并记录他们在战斗中的生活之后，我开始对他们生活的其他层面产生好奇，尤其是他们的私人生活。'), ('M', 'I can see that.', '我能理解。'), ('M', 'Your novel is about soldiers and it focuses on their relationships, especially the bond between sons and mothers and men and their wives.', '你的小说聚焦于士兵，着眼于他们的人际情感羁绊，尤其是母子之间以及丈夫与妻子之间的深厚情感。'), ('W', 'Yes. That focus came about when I still intended to write another book of history.', '是的。这一关注焦点是在我最初仍打算写另一本历史著作时萌生的。'), ('W', "I started by researching soldiers' actual personal lives, studying their letters home.", '我最初通过研究士兵真实的个人生活，细读他们寄回家的家书。'), ('M', 'So how did that history book become a novel?', '那么这本历史书又是如何演变成一部小说的呢？'), ('W', 'Well, I realized that the historical record was incomplete.', '嗯，我意识到现存的历史文献记录并不完整。'), ('W', "So I'd either have to leave a lot of gaps or make a lot more assumptions than a historian should.", '因此，要么我得留下大量的空白，要么我就必须做出远超一名历史学者应有的主观臆断。'), ('M', 'But why write a novel set in the future when your credentials are perfect for a historical novel?', '但既然你的资历背景写历史小说最为合适，为何偏偏要写一部以未来为背景的小说呢？'), ('M', 'As a historian, any historical novel you write would have a lot of credibility.', '作为一名历史学家，你写的任何历史小说都会具有很高的公信力。'), ('W', 'I felt too constrained working with the past, like what I wrote needed to be fact as opposed to fiction.', '我觉得与过去打交道束缚感太强，仿佛我写下的每一个字都必须是确凿史实而不能有虚构。'), ('W', 'But writing about the future gave me more freedom to imagine, to invent.', '而描写未来赋予了我更广阔的自由去尽情想象、肆意创造。'), ('M', "Well, having read your book, I'm glad you made that choice to move into fiction.", '读过你的新书后，我由衷为你选择跨界进军小说领域而感到高兴。')]}, {'id': '2021-12-set1-pass-1', 'subpart_code': 'pass-1', 'section_id': '2021-12-set1-sec-b', 'section_title': 'Section B: Passages', 'type': 'passage', 'title': 'Passage 1 · 可口可乐弧形经典玻璃瓶诞辰百年与设计灵感起源', 'topic_zh': '可口可乐弧形经典玻璃瓶诞辰百年与设计灵感起源', 'question_range': 'Q9 ~ Q11', 'questions': [9, 10, 11], 'sp_start': 467.0, 'sp_end': 575.0, 'sentences': [('Speaker', "Whether it's in the hands of animated polar bears or Santa Claus, there's one thing you'll find in nearly all ads for Coca-Cola: the characteristic glass bottle.", '无论是在动画北极熊的手中还是在圣诞老人的手里，几乎所有可口可乐广告中都能见到一样东西：那就是标志性的弧形玻璃瓶。'), ('Speaker', "Most Americans don't drink soda out of the glass bottles seen in Coke's ads anymore.", '如今大多数美国人已经不再像可乐广告里那样用玻璃瓶喝苏打汽水了。'), ('Speaker', "But this week, the company is celebrating a century of the bottle that's been sold in more than 200 countries.", '但本周，可口可乐公司正在庆祝这款畅销两百多个国家与地区的经典玻璃瓶诞生一百周年。'), ('Speaker', 'Flash back to 1915, when a bottle of Coca-Cola cost just a nickel.', '回溯到1915年，当时一瓶可口可乐的售价仅为五分钱（一枚镍币）。'), ('Speaker', "As the soft drink gained in popularity, it faced a growing number of competitors—counterfeits even trying to copy Coke's logo.", '随着这款软饮料日益流行，它面临着越来越多的竞争对手——仿冒伪劣产品甚至企图直接剽窃可口可乐的商标标识。'), ('Speaker', "So, according to Coca-Cola historian Ted Ryan, the company decided to come up with packaging that couldn't be duplicated.", '因此，据可口可乐历史学家泰德·瑞安介绍，公司决定构思设计一种独一无二、绝不可能被仿造复制的包装。'), ('Speaker', 'A product request was sent to eight different glass makers.', '一份产品设计需求被发送给了八家不同的玻璃制造厂商。'), ('Speaker', 'Workers at the Root Glass Company got the request and began flipping through the encyclopedia at the local library, landing on cocoa seed.', '鲁特玻璃公司的工人们收到需求后，便开始在当地图书馆翻阅百科全书，最终锁定了可可豆种子的图案。'), ('Speaker', "Though cocoa seed is not an ingredient of the soda, they designed their bottle based on the seed's shape and large middle.", '尽管可可豆并不是这种苏打汽水的原料成分，但他们依据可可种子的优美外形和中间圆鼓的特征设计了瓶身。'), ('Speaker', 'It won over Coke executives in Atlanta and would go on to receive its own trademark, spur collections and earn Coca-Cola an iconic image that made it part of American culture for a century.', '这一设计赢得了亚特兰大可乐公司高管的青睐，随后获得了专属注册商标，引发了全球收藏热潮，并为可口可乐树立了标志性形象，使之成为长达一个世纪的美国文化象征。'), ('Speaker', 'It was 100 years ago this week that the bottle earned a patent.', '正是一百年前的这一周，该经典瓶身获得了专利授权。'), ('Speaker', 'By World War II, Coke bottle sales had ballooned into billions.', '到第二次世界大战时，可口可乐瓶装饮料的销量已猛增至数十亿瓶之巨。'), ('Speaker', "Americans mostly consume Coke out of aluminum or plastic today, but the glass bottle remains a symbol of America that's readily recognized around the world.", '如今美国人饮用可乐大多使用铝罐或塑料瓶，但这款玻璃瓶依然是举世公认的美国文化标志。')]}, {'id': '2021-12-set1-pass-2', 'subpart_code': 'pass-2', 'section_id': '2021-12-set1-sec-b', 'section_title': 'Section B: Passages', 'type': 'passage', 'title': 'Passage 2 · 陌生人简短社交互动的心理增益与社交焦虑破解', 'topic_zh': '陌生人简短社交互动的心理增益与社交焦虑破解', 'question_range': 'Q12 ~ Q15', 'questions': [12, 13, 14, 15], 'sp_start': 638.0, 'sp_end': 745.5, 'sentences': [('Speaker', 'Research shows that a few moments of conversation with a stranger creates a measurable improvement in mood.', '科学研究表明，与陌生人哪怕只有片刻的简短交流，也能带来显著而可衡量的心情改善。'), ('Speaker', 'But most of us are reluctant to start these conversations because we presume the opposite.', '但我们大多数人却往往不愿开启这种交流，因为我们总主观臆断情况会恰恰相反。'), ('Speaker', "In an experiment, commuters who talked to nearby strangers found their commute more enjoyable than those who didn't.", '在一项实验中，与邻座陌生人交谈的通勤者发现，他们的通勤过程比那些不与人交谈的人要愉快得多。'), ('Speaker', "They were asked to predict whether they'd enjoy the commute more if they conversed with other people.", '他们此前被要求预测如果与其他人搭话，自己是否会更享受通勤时光。'), ('Speaker', 'Intriguingly, most expected the more solitary experience to be more pleasurable.', '耐人寻味的是，绝大多数人原本都预计独处不语的体验会更加舒适愉快。'), ('Speaker', 'Why is this?', '为什么会这样呢？'), ('Speaker', 'Social anxiety appears to be the problem.', '社交焦虑似乎正是症结所在。'), ('Speaker', "People's reluctance to start conversations with nearby strangers comes partly from 'underestimating others' interest in connecting'.", '人们之所以不愿与身旁的陌生人搭讪，部分源于“严重低估了对方建立连接与交流的兴趣”。'), ('Speaker', "The sad thing is that people presume that a nearby stranger doesn't want to converse and don't start a conversation.", '可悲的是，人们总先入为主地假定周围的陌生人根本不想聊天，因而索性闭口不谈。'), ('Speaker', 'Only those who forced themselves to chat because it was required by the experiment found out what a pleasant experience it could be.', '只有那些因为实验要求而勉强自己开口交谈的人，才真正体会到了这种互动能带来多么愉悦的体验。'), ('Speaker', 'Human beings are social animals.', '人类归根结底是高度群居的社交动物。'), ('Speaker', 'Those who misunderstand the impact of social interactions may not, in some contexts, be social enough for their own well-being.', '那些误解了社交互动积极影响的人，在某些情境下可能无法为了自身的幸福感而保持足够的社交参与。'), ('Speaker', 'You should be chatting with the strangers you encounter.', '你应当主动与身旁偶遇的陌生人攀谈两句。'), ('Speaker', 'You may occasionally have a negative encounter that might stick in your memory.', '你偶尔可能会经历一次让人尴尬不适的遭遇，并在脑海中挥之不去。'), ('Speaker', 'This is because the human brain is biased to dwell on negative events.', '这是因为人类大脑天生具有偏好沉溺于负面事件的认知偏见。'), ('Speaker', 'But starting conversations with strangers is still well worth the risk of rejection.', '但主动向陌生人开启对话，依然完全值得冒这点被拒绝的微小风险。'), ('Speaker', 'It may surprise you that conversing with strangers will make them happier too.', '或许会让你感到惊讶的是，与陌生人攀谈同样也会让他们感到更加快乐。'), ('Speaker', 'The pleasure of connection seems contagious.', '人际连接所带来的愉悦感似乎是极具感染力的。'), ('Speaker', 'People who are talked to have equally positive experiences as those who initiate a conversation.', '被搭话者所获得的积极愉悦体验，与主动发起交谈者相比毫不逊色。')]}, {'id': '2021-12-set1-rec-1', 'subpart_code': 'rec-1', 'section_id': '2021-12-set1-sec-c', 'section_title': 'Section C: Recordings', 'type': 'recording', 'title': 'Recording 1 · 加勒比群岛农业经济支柱、物产特色与贫富悬殊现状', 'topic_zh': '加勒比群岛农业经济支柱、物产特色与贫富悬殊现状', 'question_range': 'Q16 ~ Q18', 'questions': [16, 17, 18], 'sp_start': 853.0, 'sp_end': 1038.0, 'sentences': [('Speaker', 'The Caribbean islands are divided into two worlds, a rich one and a poor one.', '加勒比群岛被划分为两个截然不同的世界：一个富庶繁华，一个贫困窘迫。'), ('Speaker', "This tropical region's economy is based mainly on farming.", '这一热带地区的经济命脉主要建立在农业种植之上。'), ('Speaker', 'Farmers are of two types.', '当地农人主要分为两大阶层。'), ('Speaker', 'One is the plantation owner who may have hundreds of thousands of acres.', '一类是坐拥数十万英亩广袤土地的庄园大地主。'), ('Speaker', 'In contrast, the small cultivator is working only a few acres of land.', '相比之下，小自耕农则只能在区区数英亩的薄田上辛勤劳作。'), ('Speaker', 'Most visitors to the Caribbean are rich, like the plantation owner.', '前往加勒比海度假的大多数游客都很富有，生活境遇堪比大庄园主。'), ('Speaker', 'They do not realize or do not want to realize that many farm families barely managed to get by on what they grow.', '他们根本没有意识到、或者根本不愿去正视，当地许许多多的农耕家庭仅靠地里微薄的收成勉强糊口度日。'), ('Speaker', 'The Caribbean produces many things.', '加勒比地区物产丰富。'), ('Speaker', 'Sugar is the main product.', '蔗糖是其最主要的支柱农产品。'), ('Speaker', 'Other export crops are tobacco, coffee, bananas, spices and citrus fruits, such as orange, lemon or grapefruit.', '其他出口经济作物包括烟草、咖啡、香蕉、香料以及柑橘类水果，如甜橙、柠檬或西柚。'), ('Speaker', 'From the West Indies also come oil, mineral pitch and many forest products.', '西印度群岛还出产石油、沥青矿以及大量的林业产品。'), ('Speaker', "Jamaica's aluminum ore supplies are the world's largest.", '牙买加的铝土矿储量高居世界榜首。'), ('Speaker', 'Oil comes from Trinidad, Aruba and Curacao.', '石油则主要产自特立尼达、阿鲁巴和库拉索。'), ('Speaker', 'But for many of the smaller islands, sugar is the only export.', '但对于许多面积较小的岛屿而言，蔗糖几乎是唯一的出口命脉。'), ('Speaker', 'Rum, a strong alcoholic drink, which is distilled from sugar cane, is also an export.', '朗姆酒——一种由甘蔗蒸馏酿造的烈酒——也是大宗出口产品。'), ('Speaker', "The world's best rum comes from this area.", '世界上最优质上乘的朗姆酒便诞生于此。'), ('Speaker', 'Local kinds vary from the light rums of Puerto Rico to the heavier darker rums of Barbados and Jamaica.', '当地品种繁多，从波多黎各的清淡朗姆酒，到巴巴多斯和牙买加浓郁醇厚、色泽深沉的黑朗姆酒应有尽有。'), ('Speaker', "American tourists enjoy stocking up on inexpensive high quality Caribbean rum while they're on vacation.", '美国游客在度假期间特别热衷于大量采购物美价廉的优质加勒比朗姆酒。'), ('Speaker', 'In Curacao, the well-known liquor of that name is made from the thick outer skin of a native orange.', '在库拉索岛，以此岛命名的著名利口酒是用当地特产柑橘的厚外皮浸酿而成的。'), ('Speaker', "Ever since America's colonial days, the Caribbean islands have been favorite places to visit.", '早在北美殖民地时代起，加勒比群岛就是备受青睐的度假胜地。'), ('Speaker', 'Since World War II, tourism has increased rapidly.', '二战结束以来，当地的旅游业迎来了飞速爆发式增长。'), ('Speaker', 'Because great numbers of people go there, the islanders have built elaborate resorts, developed harbors and airfields, improved the beaches and have expanded sea and air routes.', '由于涌入的游客络绎不绝，岛民们兴建了奢华精致的度假村，开辟了深水港口与机场跑道，修整了海滩，并大幅拓展了海空航线。'), ('Speaker', 'Everything is at the resort—hotel, beach, shopping and recreation.', '度假村内一应俱全——豪华酒店、阳光海滩、精品购物与休闲娱乐应有尽有。'), ('Speaker', 'The vacationer never has any reason to explore the island.', '度假者完全没有任何理由踏出度假村去探索真实的岛屿。'), ('Speaker', 'As in most places, those who have money live well indeed.', '如同世界上大多数地方一样，有钱人的生活确实优渥奢华。'), ('Speaker', "Those who don't have money live at various levels of poverty.", '而那些囊中羞涩的穷人则挣扎在不同程度的赤贫线边缘。'), ('Speaker', 'But here the poor greatly outnumber the wealthy.', '但在加勒比群岛，贫困人口在数量上远远压倒了富人阶层。'), ('Speaker', 'A visitor will find rich people living in apartments or Spanish houses at the seaside or in the countryside.', '游客会看到富豪们居住在海滨或乡间的高档公寓或西班牙式奢华别墅中。'), ('Speaker', 'Their servants might include a cook, a maid, and a nurse for their children.', '他们的仆役成群，可能配备了厨师、女佣以及照顾幼童的专属保姆。'), ('Speaker', 'Most of the people live well below the poverty level.', '然而绝大多数普通岛民的生活水平都远远低于贫困线。'), ('Speaker', 'In towns, they live crowded together in tiny houses.', '在城镇里，他们密密麻麻地挤在狭窄破旧的小屋里。'), ('Speaker', 'Islanders make the best they can of what they have.', '岛民们竭尽所能利用手头有限的一切资源维持生计。'), ('Speaker', 'Their homes are quite shabby.', '他们的居所极其简陋破败。'), ('Speaker', 'Sadly, most tourists never see this side of the Caribbean.', '令人唏嘘的是，绝大多数游客永远也看不到加勒比海这真实而残酷的另一面。')]}, {'id': '2021-12-set1-rec-2', 'subpart_code': 'rec-2', 'section_id': '2021-12-set1-sec-c', 'section_title': 'Section C: Recordings', 'type': 'recording', 'title': 'Recording 2 · 现代家庭育儿误区、延迟满足能力与逆境韧性培养', 'topic_zh': '现代家庭育儿误区、延迟满足能力与逆境韧性培养', 'question_range': 'Q19 ~ Q21', 'questions': [19, 20, 21], 'sp_start': 1099.0, 'sp_end': 1268.0, 'sentences': [('Speaker', "Talk to anyone who's a generation not too older and they would most likely comment that children are more spoiled these days.", '你去跟任何一位年长一些的长辈聊聊天，他们大概率都会感慨如今的孩子被宠坏得越来越厉害了。'), ('Speaker', 'No one wants to have or be around demanding, selfish and spoiled children, those who get bad-tempered or silently-brute when they are not given everything they want immediately.', '没有人愿意抚养或接触那些贪得无厌、自私任性且被宠溺过度的孩子——那些只要没立刻得到想要的一切就大发雷霆或暗自生闷气的孩子。'), ('Speaker', 'Paradoxically, the parents of such children encourage this demanding behavior in the mistaken belief that by giving their children everything they can their children will be happy.', '自相矛盾的是，这些孩子的父母之所以纵容这种任性苛求，竟是错误地以为只要倾尽所有满足孩子，孩子们就能获得快乐。'), ('Speaker', 'In the short term, perhaps they are right.', '从短期来看，或许他们的愿望确实达到了。'), ('Speaker', 'But in the longer term, such children end up lonely, dependent, chronically dissatisfied and resentful of the parents who tried so hard to please them.', '但从长远来看，这些孩子最终会变得内心孤独、严重依赖、长期牢骚不满，甚至深深怨恨那些当年拼命讨好满足他们的父母。'), ('Speaker', 'Undoubtedly parents want to raise happy children who are confident, capable and likable rather than spoiled and miserable.', '毫无疑问，全天下的父母都渴望培养出自信能干、讨人喜爱且身心快乐的孩子，而非自私被宠坏且痛苦乖戾的人。'), ('Speaker', "One factor hindering this is that parents can't or don't spend enough quality time with their kids, and substitute this deficit with toys, games, gadgets and the like.", '阻碍达成这一目标的一个关键症结在于：父母无法或不愿抽出足够的优质时间陪伴孩子，反而用玩具、游戏机和电子设备等物质手段来弥补这种陪伴的缺失。'), ('Speaker', "Rather than getting material things, children need parents' devoted attention.", '相比于琳琅满目的物质馈赠，孩子们更渴望得到父母全神贯注的倾注与关爱。'), ('Speaker', 'The quantity of time spent together is less important than the content of that time.', '共同相处的时间长短，远不如共处时光的具体质量与内容来得重要。'), ('Speaker', "Instead of instantly satisfying their wishes, parents should help them work out a plan to earn things they'd like to have.", '父母不应即刻迎合孩子的每项要求，而应当引导孩子制定切实可行的规划，通过自身努力去争取心仪的物品。'), ('Speaker', 'This teaches them to value the effort as well as what it achieves.', '这能教会他们既懂得珍惜辛勤付出的汗水，也懂得敬畏奋斗所换来的成果。'), ('Speaker', 'Allow them to enjoy anticipation.', '要让孩子们学会品尝并享受期待的滋味。'), ('Speaker', 'Numerous psychological studies have demonstrated that children who learn to wait for things they desire are more likely to succeed in a number of ways later in life.', '海量心理学实证研究早已证明：学会耐心等待心仪之物的儿童，在成年后的诸多生活与事业维度上更容易取得卓越成就。'), ('Speaker', 'One famous experiment in the 1960s involved 3- to 6-year-old children.', '上世纪60年代一项著名的心理学实验以3至6岁的幼童为研究对象。'), ('Speaker', 'They were given a choice between receiving a small reward, such as a cookie, immediately, or if they waited 15 minutes, they could have two.', '孩子们面临抉择：是立刻领取一块小饼干作为奖励，还是耐心等待15分钟以获得两块饼干。'), ('Speaker', 'Follow up studies have found that those who chose to delay satisfaction are now more academically successful, have greater self-worth, and even tend to be healthier.', '后续跟踪研究证实，那些当年选择延迟满足的孩子，在学业上取得了更大突破，自我价值认同感更高，甚至身体健康状况也普遍更佳。'), ('Speaker', 'If they fail, children should be encouraged to keep trying rather than to give up if they really want the desired result.', '当遭遇失败挫折时，如果孩子们真心渴望实现预期目标，就应当鼓励他们坚韧不拔地继续尝试，而不是轻易放弃。'), ('Speaker', 'This teaches them how to handle and recover from disappointment, which is associated with greater success and satisfaction academically, financially and in personal relationships.', '这能教会孩子如何直面失望并从挫折中快速复原，而这种逆商韧性与未来在学业、财富以及人际关系各领域斩获更高成就和满足感紧密相连。'), ('Speaker', 'And lastly, parents should encourage their children to look at life from other points of view, as well as their own.', '最后，父母还应鼓励孩子学会在关注自我之余，懂得站在他人的立场与视角来审视世界。'), ('Speaker', 'This teaches them to be understanding of and sympathetic towards others—qualities sure to take them a long way in life.', '这能教会他们学会理解他人并心怀同理悲悯之情——而这些优良品质必将在人生的长跑中助他们行稳致远。')]}, {'id': '2021-12-set1-rec-3', 'subpart_code': 'rec-3', 'section_id': '2021-12-set1-sec-c', 'section_title': 'Section C: Recordings', 'type': 'recording', 'title': 'Recording 3 · 求职面试成功法则、禁忌言行与职场自驱力要求', 'topic_zh': '求职面试成功法则、禁忌言行与职场自驱力要求', 'question_range': 'Q22 ~ Q25', 'questions': [22, 23, 24, 25], 'sp_start': 1333.0, 'sp_end': 1499.5, 'sentences': [('Speaker', 'It is not hard to mess up an interview.', '要搞砸一场求职面试其实再容易不过了。'), ('Speaker', 'Most people feel nervous sitting across from a hiring manager, answering questions that effectively open themselves up for judgment.', '绝大多数人坐在招聘主管对面都会感到焦虑紧张，在回答问题时毫无保留地将自己置于被审视与评判的境地。'), ('Speaker', 'And your chances of being more carefully considered for the job can quickly go downhill just by saying the wrong thing at the wrong time.', '只要在错误的时机说错了一句话，你被重点纳入录用考量的机会就可能瞬间付诸东流。'), ('Speaker', 'The most obvious thing not to do is complain.', '面试中最显而易见的绝对禁忌就是怨天尤人、大发牢骚。'), ('Speaker', 'Employers want to hire positive people.', '用人单位真正渴望招募的是态度积极向上的人才。'), ('Speaker', 'Talking about a previous job negatively raises concerns that you might be difficult to manage, or you might be someone that blames management for your own poor performance.', '消极抱怨前任雇主或工作，会让面试官严重担忧你难以管理沟通，或者认为你是一个习惯将自身糟糕业绩归咎于管理层的推责者。'), ('Speaker', "Don't say that you've moved around in jobs because you haven't found the right fit or felt that you were not challenged enough.", '切忌声称自己之所以频繁跳槽是因为“没找到契合的定位”或“觉得缺乏足够的挑战”。'), ('Speaker', 'Statements like these will make you sound aimless and lost.', '类似的说辞只会让你听起来毫无职业目标、迷茫涣散。'), ('Speaker', 'An interviewer may well think, why would this role be any different for you?', '面试官极有可能会暗自揣测：凭什么这份新工作对你来说就会有什么两样呢？'), ('Speaker', 'You will probably leave here in six months.', '你很可能在这里干不满半年就又会拍屁股走人。'), ('Speaker', 'It also begs the question of what type of relationship you had with your manager.', '这还会让人怀疑你此前究竟与直属领导保持着怎样的工作关系。'), ('Speaker', "It doesn't sound like you had open communication with him or her.", '听起来你似乎根本不具备与上级开诚布公坦诚沟通的能力。'), ('Speaker', 'Managers usually love people who can self-sustain and enable growth through taking initiative, who are strong at following through their work, and who bring ideas and solutions to the table.', '管理者通常青睐那些能够自我驱动、通过积极主动赋能成长、具备强大执行力以落实工作，并能主动提出创见与解决方案的员工。'), ('Speaker', 'If you were in a management or leadership position, when discussing your current role, never take all the credit for accomplishments or achievements.', '若你曾担任管理或领导岗位，在谈及过往成绩与辉煌战果时，切莫把功劳全揽在自己一人身上。'), ('Speaker', 'Emphasize your team and how through their talents, your vision was realized.', '务必多强调团队的协同力量，以及正是凭借团队成员的才华，你的战略愿景才得以顺利落地实现。'), ('Speaker', 'Most successful leaders know that they are only as good as their team.', '大多数卓越的领袖都心知肚明：团队的高度决定了领导者自身的高度。'), ('Speaker', 'And acknowledging this in an interview will go a long way towards suggesting that you might be the right person for the position you are applying for.', '在面试中坦然肯定团队贡献，将极大彰显你的领导风范，证明你正是该职位的理想人选。'), ('Speaker', "Lastly, have a good idea of what your role will be and try and convey the idea that you're flexible.", '最后，要对自身应聘岗位的职责有透彻认知，并尽力展现出高度的灵活性与适应性。'), ('Speaker', 'Asking what your role will be suggests you will limit yourself purely to what is expected of you.', '一味反复询问岗位职责范围，会给人留下你只想被动画地为牢、只愿完成最低限度要求的刻板印象。'), ('Speaker', 'In reality, your role is whatever you make of it.', '而现实职场中，你的角色与价值完全取决于你自身的积极作为与创造。'), ('Speaker', 'This is especially true in small companies, where the ability to adapt and take on new responsibilities is highly valued.', '在初创及小型企业中尤为如此，快速拥抱变化并勇于挑起新职责的能力备受倚重。'), ('Speaker', "And this is equally important if you're just starting out.", '对于初入职场的新人而言，这一点同样至关重要。'), ('Speaker', 'Entry level interviewees would do well to demonstrate a broad set of skills in most interviews.', '初入职场的应聘者若能在面试中展现出多元复合的技能储备，将大幅增加胜算。'), ('Speaker', "It's important to have a wide skill set as many startups and small companies are moving really fast.", '拥有广博的技能至关重要，因为许多初创公司和中小企业的发展节奏极其迅猛。'), ('Speaker', 'Employers are looking for candidates that are intelligent and can quickly adapt and excel in a growing company.', '雇主们都在苦苦寻觅那些头脑聪慧敏锐、能在高速发展的企业中快速适应并出类拔萃的实干人才。')]}]

QUESTIONS = {1: {'prompt': 'What does Sarah think David was doing for the last two weeks?', 'options': {'A': 'He was enjoying his holiday.', 'B': 'He was recovering in hospital.', 'C': 'He was busy writing his essays.', 'D': 'He was fighting a throat infection.'}, 'answer': 'A', 'explanation': '【精析】细节辨认题。对话开头，萨拉提到：“We thought you had disappeared on holiday early or something.”萨拉和同学们以为大卫提前去休假享受假期了。因此答案为 A)。'}, 2: {'prompt': 'What happened to David on his way back from the hospital?', 'options': {'A': 'He broke his wrist.', 'B': 'He lost his antibiotics.', 'C': 'He slipped on ice and fell.', 'D': 'He was laughed at by some girls.'}, 'answer': 'C', 'explanation': '【精析】细节辨认题。大卫在从医院回来的路上说：“on the way back from the hospital, I slipped on some ice and fell and then had to go to the hospital to get an X-ray.”他在结冰的路面上滑倒摔伤。因此答案为 C)。'}, 3: {'prompt': 'What does Sarah say they should do with the damaged computer?', 'options': {'A': 'Turn to her father for help.', 'B': 'Call the repair shop to fix it.', 'C': 'Ask the manufacturer for repairs.', 'D': 'Replace it with a brand-new one.'}, 'answer': 'B', 'explanation': '【精析】细节辨认题。得知电脑刚过保修期三天后，萨拉提议：“Listen, I have the number of a really good, affordable computer repair shop at home... we can call the repair shop.”萨拉建议给技术高超的电脑维修店打电话修理电脑。因此答案为 B)。'}, 4: {'prompt': 'What does Sarah say she is going to do?', 'options': {'A': 'Help David retrieve his essays.', 'B': 'Introduce David to her parents.', 'C': 'Offer David some refreshments.', 'D': 'Accompany David to his home.'}, 'answer': 'C', 'explanation': "【精析】细节辨认题。萨拉在对话最后提议：“Let's go back to my house and we can call the repair shop, and you can have some tea and cookies too.”萨拉邀请大卫去她家喝茶吃点心（tea and cookies 即 refreshments）。因此答案为 C)。"}, 5: {'prompt': 'What does the man say about the woman?', 'options': {'A': 'She is a critic of works on military affairs.', 'B': 'She is an acclaimed hostess of Book Talk.', 'C': 'She is a researcher of literary genres.', 'D': 'She is a historian of military history.'}, 'answer': 'D', 'explanation': '【精析】细节辨认题。主持人约翰开场介绍嘉宾：“With me today is Heidi Brown, a historian who has written five critically acclaimed books about military history.”海蒂·布朗是一位著有多部广受赞誉的军事史著作的历史学家。因此答案为 D)。'}, 6: {'prompt': 'What does the woman say about her newly published book?', 'options': {'A': 'It is about the military history of Europe.', 'B': 'It is set in the 18th and 19th centuries.', 'C': 'It is her fifth book of military history.', 'D': 'It is a war novel set in the future.'}, 'answer': 'D', 'explanation': "【精析】细节辨认题。关于新出版的著作，女士介绍说：“it's not just a work of fiction. It's set 200 years in the future.”并且小说以士兵和战地人物关系为主角。因此答案为 D)。"}, 7: {'prompt': 'What did the woman do before writing her new book?', 'options': {'A': "She visited soldiers' wives and mothers.", 'B': 'She conducted surveys of many soldiers.', 'C': 'She met a large number of soldiers in person.', 'D': 'She looked into the personal lives of soldiers.'}, 'answer': 'D', 'explanation': "【精析】细节辨认题。女士讲述创作缘起时表示：“I started by researching soldiers' actual personal lives, studying their letters home.”在动笔前她深入研究了士兵的个人真实生活与家书。因此答案为 D)。"}, 8: {'prompt': 'What does the woman say about her writing history books?', 'options': {'A': "She doesn't have much freedom for imagination.", 'B': 'It is not easy to make her readers believe in her.', 'C': 'It is difficult to attract young readers.', 'D': 'She has to combine fact with fiction.'}, 'answer': 'A', 'explanation': '【精析】细节辨认题。谈及写历史著作与小说的差别，女士坦言：“I felt too constrained working with the past, like what I wrote needed to be fact as opposed to fiction.”撰写历史著作必须严格基于史实，缺乏发挥想象力的自由。因此答案为 A)。'}, 9: {'prompt': 'What does the passage say appears in almost all ads for Coca-Cola?', 'options': {'A': 'Santa Claus.', 'B': 'A polar bear.', 'C': 'Cocoa seeds.', 'D': 'A glass bottle.'}, 'answer': 'D', 'explanation': "【精析】细节辨认题。文章开篇指出：“there's one thing you'll find in nearly all ads for Coca-Cola: the characteristic glass bottle.”几乎所有可口可乐广告中都能看到其标志性的玻璃瓶。因此答案为 D)。"}, 10: {'prompt': 'Why did the Coca-Cola Company decide to have special packaging designed?', 'options': {'A': 'To attract customer attention.', 'B': 'To keep up with the times.', 'C': 'To combat counterfeits.', 'D': 'To promote its sales.'}, 'answer': 'C', 'explanation': "【精析】细节推断题。文中提到，随着饮料走红，“it faced a growing number of competitors—counterfeits even trying to copy Coke's logo. So... the company decided to come up with packaging that couldn't be duplicated.”公司决定设计专属独特包装是为了打击市场上层出不穷的仿冒品。因此答案为 C)。"}, 11: {'prompt': 'What do we learn about the Coca-Cola bottle designed by the Root Glass Company?', 'options': {'A': 'It resembles a picture in the encyclopedia.', 'B': 'It appears in the shape of a cocoa seed.', 'C': "It has the drink's logo in the middle.", 'D': 'It displays the image of Santa Claus.'}, 'answer': 'B', 'explanation': "【精析】细节辨认题。文中提到鲁特玻璃公司员工翻阅百科全书找到了可可种子：“they designed their bottle based on the seed's shape and large middle.”他们根据可可豆种子的外形和圆弧中部设计了这款瓶子。因此答案为 B)。"}, 12: {'prompt': 'What does research show about a conversation between strangers?', 'options': {'A': 'It often occurs among commuters.', 'B': 'It promotes mutual understanding.', 'C': 'It improves their mood considerably.', 'D': 'It takes a great deal of effort to sustain.'}, 'answer': 'C', 'explanation': '【精析】细节辨认题。文章开头首句指出：“Research shows that a few moments of conversation with a stranger creates a measurable improvement in mood.”科学研究表明，与陌生人交流片刻能够显著提升人们的情绪状态。因此答案为 C)。'}, 13: {'prompt': 'What prevents people from starting a conversation with strangers?', 'options': {'A': 'Social anxiety.', 'B': 'Excessive caution.', 'C': 'Lack of social skills.', 'D': 'Preference for solitude.'}, 'answer': 'A', 'explanation': "【精析】细节辨认题。针对人们为何不愿主动开口交流，文章指出：“Social anxiety appears to be the problem... comes partly from 'underestimating others' interest in connecting'.”社交焦虑与低估他人的交流意愿是阻碍人们主动交流的主要因素。因此答案为 A)。"}, 14: {'prompt': "Why does a negative encounter with strangers stick in one's memory?", 'options': {'A': 'People usually regard it as an unforgettable lesson.', 'B': 'Human brains tend to dwell on negative events.', 'C': 'Negative events often hurt people deeply.', 'D': 'People generally resent being rejected.'}, 'answer': 'B', 'explanation': '【精析】细节辨认题。文章解释偶尔一次尴尬负面的遭遇为何让人难以忘怀：“This is because the human brain is biased to dwell on negative events.”这是由于人类大脑天生倾向于对负面事件记忆更深刻。因此答案为 B)。'}, 15: {'prompt': 'What does the passage say the pleasure of connection seems to be?', 'options': {'A': 'Contagious.', 'B': 'Temporary.', 'C': 'Unpredictable.', 'D': 'Measurable.'}, 'answer': 'A', 'explanation': '【精析】细节辨认题。短文在结尾处明确指出：“The pleasure of connection seems contagious. People who are talked to have equally positive experiences as those who initiate a conversation.”社交连接带来的快乐是具有感染力的。因此答案为 A)。'}, 16: {'prompt': 'What does the speaker say about the economy of the Caribbean islands?', 'options': {'A': 'It depends heavily on tourism.', 'B': 'It is flourishing in foreign trade.', 'C': 'It is mainly based on agriculture.', 'D': 'It relies chiefly on mineral export.'}, 'answer': 'C', 'explanation': "【精析】细节辨认题。讲话开头指出：“This tropical region's economy is based mainly on farming.”加勒比热带地区的经济主要以农业为基础。因此答案为 C)。"}, 17: {'prompt': 'What is the main product of the Caribbean islands?', 'options': {'A': 'Tobacco.', 'B': 'Bananas.', 'C': 'Coffee.', 'D': 'Sugar.'}, 'answer': 'D', 'explanation': '【精析】细节辨认题。讲座明确指出加勒比地区的物产：“The Caribbean produces many things. Sugar is the main product.”糖是该地区最主要的产品。因此答案为 D)。'}, 18: {'prompt': 'What do we learn about the majority of people in the Caribbean islands?', 'options': {'A': 'They toil on farms.', 'B': 'They live a poor life.', 'C': 'They live in Spanish-style houses.', 'D': 'They hire people to do housework.'}, 'answer': 'B', 'explanation': '【精析】细节辨认题。讲话后半部分揭示了当地的贫富分化：“here the poor greatly outnumber the wealthy... Most of the people live well below the poverty level.”绝大多数当地人生活在贫困线以下，生活困顿。因此答案为 B)。'}, 19: {'prompt': 'What will happen to children if they always get immediate satisfaction?', 'options': {'A': 'They will be more demanding of their next generation.', 'B': 'They will end up lonely, dependent and dissatisfied.', 'C': 'They will experience more setbacks than successes.', 'D': 'They will find it difficult to get along with others.'}, 'answer': 'B', 'explanation': '【精析】细节辨认题。讲话中分析长久百依百顺对孩子的害处：“such children end up lonely, dependent, chronically dissatisfied and resentful of the parents who tried so hard to please them.”习惯即刻满足的孩子最终会变得孤独、依赖、长期不满。因此答案为 B)。'}, 20: {'prompt': 'What may prevent parents from raising confident and capable children?', 'options': {'A': 'Failure to pay due attention to their behavior.', 'B': 'Unwillingness to allow them to play with toys.', 'C': 'Unwillingness to satisfy their wishes immediately.', 'D': 'Failure to spend sufficient quality time with them.'}, 'answer': 'D', 'explanation': "【精析】细节辨认题。讲座指出阻碍父母培养能干自信孩子的关键原因：“One factor hindering this is that parents can't or don't spend enough quality time with their kids, and substitute this deficit with toys, games, gadgets and the like.”父母未能投入足够的高质量陪伴时间。因此答案为 D)。"}, 21: {'prompt': 'Why should children be encouraged to keep trying when they fail?', 'options': {'A': 'It will enable them to learn from mistakes.', 'B': 'It will help them to handle disappointment.', 'C': 'It will do much good to their mental health.', 'D': 'It will build their ability to endure hardships.'}, 'answer': 'B', 'explanation': '【精析】细节辨认题。讲话指出面对失败鼓励孩子坚持的益处：“This teaches them how to handle and recover from disappointment, which is associated with greater success and satisfaction.”这能培养孩子应对失望并从中复原的抗挫能力。因此答案为 B)。'}, 22: {'prompt': 'What does the speaker say can easily prevent an interviewee from getting a job?', 'options': {'A': 'Failing to make sufficient preparations.', 'B': 'Looking away from the hiring manager.', 'C': 'Saying the wrong thing at the wrong time.', 'D': 'Making a wrong judgment of the interview.'}, 'answer': 'C', 'explanation': '【精析】细节辨认题。讲话开篇指出搞砸面试的原因：“your chances of being more carefully considered for the job can quickly go downhill just by saying the wrong thing at the wrong time.”在不合适的时间说错话会直接断送被考虑的机会。因此答案为 C)。'}, 23: {'prompt': 'What should the interviewee avoid doing in an interview?', 'options': {'A': 'Complaining about their previous job.', 'B': 'Inquiring about their salary to be paid.', 'C': 'Exaggerating their academic background.', 'D': 'Understating their previous achievements.'}, 'answer': 'A', 'explanation': '【精析】细节辨认题。讲座明确指出首要禁忌：“The most obvious thing not to do is complain... Talking about a previous job negatively raises concerns that you might be difficult to manage.”面试中切忌抱怨之前的工作或前任雇主。因此答案为 A)。'}, 24: {'prompt': 'What kind of employees do companies like to recruit?', 'options': {'A': 'Those who have both skill and experience.', 'B': 'Those who get along well with colleagues.', 'C': 'Those who take initiative in their work.', 'D': 'Those who are loyal to their managers.'}, 'answer': 'C', 'explanation': '【精析】细节辨认题。讲座指出管理者青睐的员工特质：“Managers usually love people who can self-sustain and enable growth through taking initiative, who are strong at following through their work, and who bring ideas and solutions to the table.”管理者器重那些能够主动承担并富有积极进取心的人。因此答案为 C)。'}, 25: {'prompt': 'What is especially important for those working in a small company?', 'options': {'A': 'Ability to shoulder new responsibilities.', 'B': 'Experience of performing multiple roles.', 'C': 'Readiness to work to flexible schedules.', 'D': 'Skills to communicate with colleagues.'}, 'answer': 'A', 'explanation': '【精析】细节辨认题。针对初创或小型企业，讲话强调：“This is especially true in small companies, where the ability to adapt and take on new responsibilities is highly valued.”在小公司里，适应变化并勇于承担新职责的能力备受看重。因此答案为 A)。'}}
